#include <stdio.h>
#include <math.h>
/*
 * ex05：多道程序度 n 与 CPU 利用率
 * 经典模型（王道/汤小丹）：某作业在 I/O 上的时间比例为 p，
 *   单道时 CPU 利用率 = 1 - p
 *   n 道并发时，n 个作业同时等 I/O 的概率为 p^n，CPU 空闲的概率也是 p^n
 *   所以                   利用率 = 1 - p^n
 * 这解释了「为什么多道能提高利用率，但收益递减」。
 */
int main(void) {
    double p = 0.8;          /* 该作业 80% 的时间在等 I/O（典型交互式/数据库作业） */
    printf("作业 I/O 等待比例 p = %.2f\n", p);
    printf("----------------------------------------\n");
    printf("%-8s %-14s %s\n", "道数 n", "CPU 利用率", "相对单道提升");
    double base = 1.0 - p;
    for (int n = 1; n <= 8; n++) {
        double util = 1.0 - pow(p, n);
        printf("%-8d %-14.4f %.2fx\n", n, util, util / base);
    }
    printf("\n另一面：若把 p 降到 0.2（计算密集型），n=4 时利用率已达 %.4f\n", 1.0 - pow(0.2, 4));
    printf("结论：I/O 越重，多道收益越大；计算密集型作业多道几乎无收益，还会增加切换开销。\n");
    return 0;
}
